            case CMD_FILL: {
                let fill = read_fill(cmd_ix);
                fill_path_ms(fill, local_id.xy, &area);
                cmd_ix += 4u;
            }
            case CMD_SOLID: {
                for (var i = 0u; i < PIXELS_PER_THREAD; i += 1u) {
                    area[i] = 1.0;
